"""Subgraph service registry."""

from typing import Dict, List
from schema import SubgraphField


class FederationRegistry:
    def __init__(self):
        # Maps field_name -> SubgraphField
        self.fields: Dict[str, SubgraphField] = {}

    def register_field(self, field: SubgraphField) -> None:
        self.fields[field.name] = field

repo_files.planner.py:
"""Federated query planner assembling cross-service execution steps."""

from typing import Dict, List, Set
from schema import SubgraphField
from service_registry import FederationRegistry


class QueryPlanStep:
    def __init__(self, service: str, requested_fields: List[str]):
        self.service = service
        self.requested_fields = list(requested_fields)


class FederationQueryPlanner:
    def __init__(self, registry: FederationRegistry):
        self.registry = registry

    def plan_query(self, target_fields: List[str]) -> List[QueryPlanStep]:
        service_map: Dict[str, Set[str]] = {}
        # BUG: Only schedules requested target_fields into service buckets,
        # failing to inspect field.required_fields dependencies (like author_id for reviews)!
        for f_name in target_fields:
            field_def = self.registry.fields.get(f_name)
            if not field_def:
                continue
            svc = field_def.service_name
            if svc not in service_map:
                service_map[svc] = set()
            service_map[svc].add(f_name)
        return [QueryPlanStep(svc, sorted(fields)) for svc, fields in service_map.items()]

reference_fix.planner.py:
"""Federated query planner assembling cross-service execution steps."""

from typing import Dict, List, Set
from schema import SubgraphField
from service_registry import FederationRegistry


class QueryPlanStep:
    def __init__(self, service: str, requested_fields: List[str]):
        self.service = service
        self.requested_fields = list(requested_fields)


class FederationQueryPlanner:
    def __init__(self, registry: FederationRegistry):
        self.registry = registry

    def plan_query(self, target_fields: List[str]) -> List[QueryPlanStep]:
        service_map: Dict[str, Set[str]] = {}
        for f_name in target_fields:
            field_def = self.registry.fields.get(f_name)
            if not field_def:
                continue
            svc = field_def.service_name
            if svc not in service_map:
                service_map[svc] = set()
            service_map[svc].add(f_name)
            # Inject required prerequisite dependency fields
            for req in field_def.required_fields:
                req_def = self.registry.fields.get(req)
                if req_def:
                    req_svc = req_def.service_name
                    if req_svc not in service_map:
                        service_map[req_svc] = set()
                    service_map[req_svc].add(req)
        return [QueryPlanStep(svc, sorted(fields)) for svc, fields in sorted(service_map.items())]
